static FuncPtr recomp_find_func(uint32_t addr) {
    int lo = 0, hi = 951;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (s_dispatch_table[mid].addr < addr) lo = mid + 1;
        else hi = mid;
    }
    return (lo < 951 && s_dispatch_table[lo].addr == addr)
         ? s_dispatch_table[lo].fn : NULL;
}

int game_dispatch_table_size(void) { return 951; }
uint32_t game_dispatch_table_addr(int i) {
    return (i >= 0 && i < 951) ? s_dispatch_table[i].addr : 0;
}

static const uint32_t s_game_hook_sites[] = { 0u };
int game_instruction_hook_site(uint32_t pc) {
    int lo = 0, hi = 0;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (s_game_hook_sites[mid] < pc) lo = mid + 1;
        else hi = mid;
    }
    return lo < 0 && s_game_hook_sites[lo] == pc;
}

#ifdef GENESIS_HAS_NATIVE_CALL_FRAME
typedef GenesisNativeCallFrame RecompTailFrame;
GenesisNativeCallFrame *g_recomp_native_frame = NULL;
#define g_recomp_tail_frame g_recomp_native_frame
#define RECOMP_FRAME_INIT {0,0,g_recomp_tail_frame,NULL}
#else
typedef struct RecompTailFrame {
    int pending;
    uint32_t addr;
    struct RecompTailFrame *prev;
} RecompTailFrame;

static RecompTailFrame *g_recomp_tail_frame = NULL;
#define RECOMP_FRAME_INIT {0,0,g_recomp_tail_frame}
#endif

/* The frame list lives on the game fiber's stack and its head is
 * execution state: fiber snapshots carry it (get/set) and rollback
 * digests hash it address-free (walk, innermost frame first). */
void *recomp_tail_frame_get(void) {
    return g_recomp_tail_frame;
}

void recomp_tail_frame_set(void *frame) {
    g_recomp_tail_frame = (RecompTailFrame *)frame;
}

void recomp_tail_frame_walk(void (*visit)(int pending, uint32_t addr, void *user),
                            void *user) {
    for (const RecompTailFrame *f = g_recomp_tail_frame; f; f = f->prev)
        visit(f->pending, f->addr, user);
}

void recomp_tail_call(uint32_t addr) {
    if (!g_recomp_tail_frame) {
        fprintf(stderr, "recompiled tail call without dispatch frame at $%06X\n", addr & 0xFFFFFFu);
        exit(2);
    }
    g_recomp_tail_frame->addr = addr & 0xFFFFFFu;
#ifdef GENESIS_HAS_NATIVE_CALL_FRAME
    g_recomp_tail_frame->function = NULL;
#endif
    g_recomp_tail_frame->pending = 1;
}

static void recomp_dispatch_once(uint32_t addr) {
    addr = recomp_resolve_ram_trampoline(addr);
    if (recomp_dispatch_ram_stub(addr))
        return;
    FuncPtr fn = recomp_find_func(addr);
    if (fn) {
        fn();
        return;
    }
    if (!g_game_spec.dispatch_override || !g_game_spec.dispatch_override(addr))
        genesis_log_dispatch_miss(addr);
}

static void recomp_drain_tailcalls(RecompTailFrame *frame) {
    unsigned guard = 0;
    uint64_t guard_frame = g_frame_count;
    while (frame->pending) {
        uint32_t addr = frame->addr;
        frame->pending = 0;
#ifdef GENESIS_HAS_NATIVE_CALL_FRAME
        RecompFuncPtr native = frame->function; frame->function = NULL;
        if (native) native(); else recomp_dispatch_once(addr);
#else
        recomp_dispatch_once(addr);
#endif
        if (g_rte_pending)
            break;
        /* Native pause loops can span many yielded wall frames.
         * Bound transfers without frame progress, not their lifetime. */
        if (guard_frame != g_frame_count) {
            guard_frame = g_frame_count; guard = 0;
        }
        if (++guard > 1000000u) {
            fprintf(stderr, "recompiled tail-dispatch runaway at $%06X\n", addr);
            exit(2);
        }
    }
}

#ifdef GENESIS_HAS_NATIVE_CALL_FRAME
void recomp_native_drain(GenesisNativeCallFrame *frame) {
    recomp_drain_tailcalls(frame);
}
#endif

void recomp_call_func(RecompFuncPtr fn) {
    if (!fn)
        return;
    RecompTailFrame frame = RECOMP_FRAME_INIT;
    g_recomp_tail_frame = &frame;
    fn();
    recomp_drain_tailcalls(&frame);
    g_recomp_tail_frame = frame.prev;
}

void recomp_call_addr(uint32_t addr) {
    RecompTailFrame frame = RECOMP_FRAME_INIT;
    g_recomp_tail_frame = &frame;
    recomp_tail_call(addr);
    recomp_drain_tailcalls(&frame);
    g_recomp_tail_frame = frame.prev;
}

void call_by_address(uint32_t addr) {
    recomp_call_addr(addr);
}
